{
  "name": "mac_tx_desc_build",
  "confidence": "medium",
  "docstring": "Builds/populates a MAC TX descriptor and control block, copies source descriptor and rate-control station fields, stores a control byte, then invokes packet building and special-type event/HCI handling.",
  "subsystem": "mac",
  "var_renames": {
    "a1": "tx_info",
    "a2": "build_arg",
    "a3": "tx_ctl_byte",
    "v4": "tx_flags",
    "v5": "tx_desc",
    "v8": "tx_signed_field",
    "v9": "tx_desc",
    "v12": "desc_src",
    "v13": "desc_dst",
    "v14": "desc_src_ptr",
    "v15": "desc_word",
    "v16": "rc_sta_stats",
    "v17": "tx_desc_after_lookup",
    "v18": "rc_stats_word1",
    "v19": "rc_stats_word2",
    "v20": "packet_type",
    "v21": "global_stats_ptr",
    "v22": "packet",
    "v25": "rc_stats_word2_masked",
    "v27": "rc_stats_word2_bits",
    "v28": "rc_stats_word2_final",
    "v29": "desc_src_saved"
  },
  "struct_hints": [
    {
      "offset": 8,
      "meaning": "tx_info+8: signed status or length-like field checked for negative values"
    },
    {
      "offset": 24,
      "meaning": "tx_info+24: packet type/protocol field, with special value 36488/0x8EA8"
    },
    {
      "offset": 29,
      "meaning": "tx_info+29: station/rate-control table index used with 696-byte entries"
    },
    {
      "offset": 30,
      "meaning": "tx_info+30: uint16 flags; bit 0x2000 enables rate-control stats lookup"
    },
    {
      "offset": 36,
      "meaning": "tx_info+36: uint32 TX control flags, including 0x200000 and 0x380000 mask bits"
    },
    {
      "offset": 44,
      "meaning": "tx_info+44: pointer to source descriptor/rate table words"
    },
    {
      "offset": 72,
      "meaning": "tx_info+72: pointer to destination TX descriptor/control block"
    },
    {
      "offset": 76,
      "meaning": "tx_info+76: pointer to packet buffer; packet length appears at packet+36"
    },
    {
      "offset": 84,
      "meaning": "tx_info+84: field written from tx_info+8 in a failure/special path"
    },
    {
      "offset": 36,
      "meaning": "tx_desc+36: byte control flag copied from argument a3"
    },
    {
      "offset": 48,
      "meaning": "tx_desc+48: descriptor flags field masked based on source word tx_info_desc_src[15] bit 2"
    },
    {
      "offset": 60,
      "meaning": "tx_desc+60: flag word; ORs 0xE00 for special packet type 0x8EA8"
    },
    {
      "offset": 64,
      "meaning": "tx_desc+64: rate/control word copied from station entry offset 156"
    },
    {
      "offset": 68,
      "meaning": "tx_desc+68: descriptor field copied from source descriptor word index 5"
    },
    {
      "offset": 80,
      "meaning": "tx_desc+80: rate/control word copied from station entry offset 160 and adjusted from tx_desc flags"
    },
    {
      "offset": 84,
      "meaning": "tx_desc+84: descriptor field copied from source descriptor word index 9"
    },
    {
      "offset": 156,
      "meaning": "rate-control station entry+156: uint32 TX rate/control word 1"
    },
    {
      "offset": 160,
      "meaning": "rate-control station entry+160: uint32 TX rate/control word 2"
    },
    {
      "offset": 165,
      "meaning": "rate-control station entry+165: uint8 flag used to set/clear bit 0x40000 in tx_desc+80"
    }
  ]
}
